-- Epic Level Handbook epic rings.
-- Source: Epic Level Handbook, Chapter 4, pp. 135-137.
-- Mechanical text is summarized; source remains authoritative.
-- Market prices are exact source prices. Craft gp/XP costs are populated only where the retrieved source explicitly supplies them.

INSERT OR IGNORE INTO dnd35_sources
